module four_bit_adder_sva(
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] Z,
    input logic       Cout
);

    // Full output matches the 4-bit addition with carry-in.
    check_full_addition: assert property (
        @($global_clock)
        {Cout, Z} == ({1'b0, A} + {1'b0, B} + {{4{1'b0}}, Cin})
    );

    // Bit 0 sum matches XOR of the inputs and carry-in.
    check_sum_bit0: assert property (
        @($global_clock)
        Z[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @($global_clock)
        Z[1] == (
            A[1] ^ B[1] ^
            ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))
        )
    );

    // Bit 2 sum uses the carry generated by bit 1.
    check_sum_bit2: assert property (
        @($global_clock)
        Z[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
            )
        )
    );

    // Bit 3 sum uses the carry generated by bit 2.
    check_sum_bit3: assert property (
        @($global_clock)
        Z[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (A[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                )) |
                (B[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                ))
            )
        )
    );

    // Carry-out matches the carry generated by bit 3.
    check_cout_formula: assert property (
        @($global_clock)
        Cout == (
            (A[3] & B[3]) |
            (A[3] & (
                (A[2] & B[2]) |
                (A[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                )) |
                (B[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                ))
            )) |
            (B[3] & (
                (A[2] & B[2]) |
                (A[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                )) |
                (B[2] & (
                    (A[1] & B[1]) |
                    (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
                    (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
                ))
            ))
        )
    );

endmodule